import { CDN_URL, CDN_IMAGES_FORMAT } from '../../utils/constants';
import { getPriceString } from '../../utils/utils';
export class ItemsList {
    constructor() {
        this.items = [];
    }
    setItems(items) {
        this.items = [];
        items.forEach(item => {
            this.items.push(Object.assign(Object.assign({}, item), { priceString: getPriceString(item.price), imageLink: this.getImageLink(item.image, CDN_URL, CDN_IMAGES_FORMAT), categoryClass: this.getCategoryClass(item.category) }));
        });
    }
    getAllItems() {
        return this.items;
    }
    getItems(itemIds) {
        return this.items.filter(item => itemIds.some(itemId => itemId === item.id));
    }
    getItem(itemId) {
        return this.items.find(item => item.id === itemId);
    }
    getCategoryClass(category) {
        let categoryClass = '';
        switch (category) {
            case 'софт-скил':
                categoryClass = 'card__category_soft';
                break;
            case 'дополнительное':
                categoryClass = 'card__category_additional';
                break;
            case 'кнопка':
                categoryClass = 'card__category_button';
                break;
            case 'хард-скил':
                categoryClass = 'card__category_hard';
                break;
            case 'другое':
            default:
                categoryClass = 'card__category_other';
                break;
        }
        return categoryClass;
    }
    getImageLink(image, cdnUrl, imageFormat) {
        return cdnUrl + image.replace('.svg', '.' + imageFormat);
    }
}
