export class OrderData {
    constructor() {
        this.payment = null;
        this.address = null;
        this.email = null;
        this.phone = null;
        this.items = [];
        this.total = 0;
    }
    setOrderData(data) {
        if (data.payment)
            this.payment = data.payment;
        if (data.address)
            this.address = data.address;
        if (data.email)
            this.email = data.email;
        if (data.phone)
            this.phone = data.phone;
        if (data.items)
            this.items = data.items;
        if (data.total)
            this.total = data.total;
    }
    getOrderData() {
        return {
            payment: this.payment,
            address: this.address,
            email: this.email,
            phone: this.phone,
            items: this.items,
            total: this.total
        };
    }
}
